"""A layout move lands from `next` (`queue`'s "Moves"): a PR whose body says `Move: tools/move/MAP.toml` is regenerated by the
sync on the tip below it with `rename.py`, certified by `move_check.py`, both as the landing branch has them, and lands as that
one commit on its review; the members above it merge across it, restacked by `restack.py` in the background when the move
touches what they change.  The scripts are this checkout's, copied into a throwaway origin with a map that moves `old_proto/`
to `new_proto/`; a restack job runs only when a test runs it (`jobs`)."""
from __future__ import annotations

import dataclasses
import json
import os
import subprocess
import tempfile
from pathlib import Path

import pytest

import research.drive as D
import research.queue as Q
from research.queue import RESTACKING
from test_drive_checked import _checked, _pass
from test_drive_review import Review, _main, _move_main
from test_queue import World, _git

ROOT = Path(__file__).resolve().parents[3]
SCRIPTS = ("tools/move/rename.py", "tools/move/layout.py", "tools/move/restack.py", "tools/verity/check/move_check.py")
MAP, BAD = "tools/move/demo_map.toml", "tools/move/bad_map.toml"
EXCLUDE = '[rewrite]\nexclude = ["tools/move/**", "tools/research/src/research/store/moves.json"]\n\n'
B = "import old_proto.a\n\nX = old_proto.a.f()\n"
REGISTRY = ".agents/skills/using-slack/registry.json"


@pytest.fixture
def world(tmp_path):
    w = World(tmp_path)
    _move_main(w, {**{p: (ROOT / p).read_text() for p in SCRIPTS},
                   "tools/verity/check/pins.py": "PINS = ()\n",
                   "tools/research/src/research/store/moves.json": '{"moves": []}\n',
                   MAP: EXCLUDE + '[words]\n"old_proto" = "new_proto"\n',
                   BAD: EXCLUDE + '[words]\n"banana" = "cherry"\n',
                   "old_proto/__init__.py": "", "old_proto/a.py": "def f():\n    return 1\n", "b.py": B,
                   "fruit.py": "banana = 1\n",
                   REGISTRY: json.dumps({"handles": [{"handle": f"lane-{n}", "holder": "a lane"} for n in range(1, 5)]})})
    w.gh.closed = []
    w.gh.close = lambda n, comment: w.gh.closed.append((n, comment))
    return w


@dataclasses.dataclass
class Job:
    """A restack job a sync started, as it gave `drive.detach` the job: it runs only when a test runs it, and until it ends its
    process is the test's own, alive."""
    argv: list[str]
    cwd: Path
    env: dict[str, str]
    dir: Path

    @property
    def head(self) -> str:
        return self.argv[self.argv.index("--move-commit") - 1]

    def run(self) -> None:
        """Run it to its end as `drive.detach`'s job does: its output into `log`, its exit into `rc`."""
        subprocess.run(["sh", "-c", D.DETACH_JOB, "sh", str(self.dir), *self.argv], cwd=self.cwd, env=self.env, check=True)

    def end(self, rc: int, log: str) -> None:
        """End it with exit ``rc`` and output ``log`` and no results, as a `restack.py` killed or crashed leaves it."""
        (self.dir / "log").write_text(log)
        (self.dir / "rc").write_text(f"{rc}\n")


@pytest.fixture(autouse=True)
def jobs(monkeypatch, tmp_path) -> list[Job]:
    """Each restack job the syncs start, oldest first, under the test's own temporary directory."""
    started: list[Job] = []
    monkeypatch.setattr(tempfile, "tempdir", str(tmp_path))

    def detach(repo: Path, argv: list[str], env: dict[str, str], script: str | None = None) -> dict:
        d = Path(tempfile.mkdtemp(prefix="train-", dir=tmp_path / D.LAUNCHES))
        started.append(Job(argv, Path(repo), env, d))
        return {"dir": str(d), "pid": os.getpid()}

    monkeypatch.setattr(D, "detach", detach)
    return started


def _move_pr(world: World, n: int, map: str = MAP) -> None:
    """A move PR whose head is the request: the move as its owner made it on an older `main`."""
    head = world.change({"old_proto/__init__.py": None, "old_proto/a.py": None, "new_proto/__init__.py": "",
                         "new_proto/a.py": "def f():\n    return 1\n", "b.py": B.replace("old_proto", "new_proto")})
    world.gh.put(n, head, body=f"Lane `lane-{n}`.\nMove: {map}\n")
    world.gh.prs[n] = dataclasses.replace(world.gh.prs[n], branch=f"lane-{n}/move")
    _git(world.origin, "update-ref", f"refs/heads/lane-{n}/move", head)


def _show(world: World, ref: str, path: str) -> str:
    return _git(world.origin, "show", f"{ref}:{path}")


def _parents(world: World, ref: str) -> list[str]:
    return _git(world.origin, "rev-list", "--parents", "-n", "1", ref).split()[1:]


def _member(world: World, n: int) -> str:
    return next(c for c in _git(world.origin, "rev-list", "--first-parent", "refs/heads/next").split()
                if _git(world.origin, "log", "-1", "--format=%s", c).startswith(f"Queue: #{n} "))


def test_a_move_is_regenerated_on_a_moved_checked_certified_at_nexts_bottom_and_lands_as_one_commit(world, monkeypatch):
    h = Review(world, monkeypatch, land_into="checked")
    world.gh.put(1, world.change({"old_proto/c.py": "C = 1\n"}))    # lands first: the move must carry a file its head lacks
    _move_pr(world, 2)
    world.gh.put(3, world.change({"c.txt": "3\n"}))
    h.review(1)
    assert h.tick().startswith("landed #1"), world.logs
    tip = _checked(world)
    move = _member(world, 2)
    assert _parents(world, move) == [tip]                         # next's bottom member, one commit on `checked`'s tip
    body = _git(world.origin, "log", "-1", "--format=%B", move)
    assert f"Move: {MAP}" in body and f"Head: {world.gh.prs[2].head}" in body
    files = _git(world.origin, "ls-tree", "-r", "--name-only", move).split()
    assert "new_proto/c.py" in files and not [f for f in files if f.startswith("old_proto/")]
    assert _show(world, move, "b.py") == B.replace("old_proto", "new_proto").rstrip("\n")
    assert any(f"#2's move ({MAP}) regenerated on {tip[:12]} as {move[:12]}" in x for x in world.logs), world.logs
    assert _parents(world, _member(world, 3))[0] == move          # #3 doesn't touch the move: a plain merge above it

    h.review(2)
    assert h.tick().startswith("landed #2"), world.logs
    assert _checked(world) == move and world.on_next(h.q) == [3]
    assert any(p.startswith(f"@lane-2 queue: #2's move ({MAP}) landed on `checked` as {move[:12]}") for p in h.posts), h.posts
    h.tick()
    assert world.on_next(h.q) == [3]                              # still open at a head `checked` lacks: not admitted again
    st = h.q.status()
    assert st[2].state == "queued" and st[2].why.startswith("landed on `checked`"), st[2]
    _pass(h)                                                      # #1's after-landing run, then the move's
    h.tick()
    assert _main(world) == tip and world.gh.closed == []
    _pass(h)
    h.tick()
    assert _main(world) == move
    assert world.gh.closed == [(2, f"Landed in `main` at {move[:12]}: its move ({MAP}), regenerated by drive as {move[:12]}.")]
    assert any(p.startswith("@lane-2 queue: #2 landed in `main`") and "drive closed it" in p for p in h.posts), h.posts
    assert not _git(world.origin, "for-each-ref", "refs/heads/lane-2/move"), "drive deletes a PR's branch once it closes it"
    assert any(f"deleted origin's lane-2/move, #2's head at {world.gh.prs[2].head[:12]}" in x for x in world.logs), world.logs


def test_a_move_whose_map_rewrites_a_locks_frozen_reason_enters_next(world, monkeypatch):
    """The move rewrites the moved path where a lock's frozen entry names it; that rewrite is the certified move, not a dropped
    entry, so the sync's lock-drop check doesn't keep the move out."""
    lock = {"guarantees": {"G": {"statement": "s"}}, "shape": {"frozen": {"G": "frozen: old_proto.a's bound"}}}
    _move_main(world, {"lean/P/lean-audit.json": json.dumps(lock, indent=1) + "\n"})
    h = Review(world, monkeypatch, land_into="checked")
    _move_pr(world, 1)
    h.tick()
    move = _member(world, 1)
    assert "new_proto.a's bound" in _show(world, move, "lean/P/lean-audit.json")
    assert not any("drops" in x and "#1" in x for x in world.logs), world.logs


def test_a_member_the_move_touches_waits_while_it_is_restacked_in_the_background_then_merges_restacked(world, monkeypatch, jobs):
    """The sync that meets a head the move's map touches doesn't wait for its restack: it starts it in the background, and one
    for each head above it the map touches (#3, built on #2), and keeps them off `next` meanwhile, a wait that refuses nothing
    and rings no one.  A later sync finds the jobs running and starts none; once #2's ended, it merges #2 restacked."""
    h = Review(world, monkeypatch, land_into="checked")
    _move_pr(world, 1)
    head = world.change({"b.py": B.replace("f()", "f() + 1"), "old_proto/d.py": "D = 1\n"})
    world.gh.put(2, head)
    world.gh.put(3, three := world.change({"c.txt": "3\n"}, base=head))
    h.tick()
    move = _member(world, 1)
    restacking = f"{RESTACKING} {move[:12]} ({MAP}) since 13:46 UTC"
    assert world.on_next(h.q) == [1] and [j.head for j in jobs] == [head, three], world.logs
    st = h.q.status()
    assert st[2].state == "waiting" and st[2].why.startswith(restacking), st[2]
    assert st[3].state == "waiting" and st[3].why.startswith("contains #2"), st[3]
    assert any(f"#2 at {head[:8]} waits off `next`: {restacking}" in x for x in world.logs), world.logs
    assert h.q.load_state()["conflicts"] == {} and not [p for p in h.posts if "#2" in p], h.posts
    h.clock += 600
    h.tick()
    assert len(jobs) == 2 and world.on_next(h.q) == [1], world.logs
    jobs[0].run()
    h.tick()
    assert world.on_next(h.q) == [1, 2], world.logs
    two = _member(world, 2)
    first, restacked = _parents(world, two)
    assert first == move and restacked != head
    assert _git(world.origin, "merge-base", "--is-ancestor", head, restacked) == ""
    assert _show(world, two, "b.py") == "import new_proto.a\n\nX = new_proto.a.f() + 1"
    assert _show(world, two, "new_proto/d.py") == "D = 1"
    assert any(f"#2 at {head[:8]} restacked through the move" in x for x in world.logs), world.logs
    assert h.q.status()[3].why.startswith(restacking) and not [p for p in h.posts if "#2" in p or "#3" in p], h.posts


def test_restacks_run_side_by_side_up_to_restack_jobs_and_another_starts_once_one_ended(world, monkeypatch, jobs):
    """Each head is a `restack.py` of its own, at most `restack_jobs` at once: the sync that meets three heads to restack
    starts two, the third waiting for a free one, and the sync after one of them ended starts it."""
    h = Review(world, monkeypatch, land_into="checked")
    h.q.restack_jobs = 2
    _move_pr(world, 1)
    heads = {n: world.change({f"old_proto/x{n}.py": f"X = {n}\n"}) for n in (2, 3, 4)}
    for n, head in heads.items():
        world.gh.put(n, head)
    h.tick()
    what = f"{RESTACKING} {_member(world, 1)[:12]} ({MAP})"
    assert [j.head for j in jobs] == [heads[2], heads[3]] and world.on_next(h.q) == [1], world.logs
    st = h.q.status()
    assert st[3].state == "waiting" and st[3].why.startswith(f"{what} since 13:46 UTC"), st[3]
    assert st[4].state == "waiting" and st[4].why.startswith(f"{what} once one of the 2 restacks running ends"), st[4]
    jobs[0].run()
    h.tick()
    assert world.on_next(h.q) == [1, 2] and [j.head for j in jobs] == [heads[2], heads[3], heads[4]], world.logs


def test_a_restack_job_that_ends_with_no_result_runs_once_more_and_then_its_failure_refuses_the_pr(world, monkeypatch, jobs):
    """A job killed (here with exit 137 and no results) runs once more, still waiting since its first start; when that one
    writes no exit within `RESTACK_LOST_S` too, the restack failed: the PR is refused with the tail, and its owner told, as a
    `restack.py` that fails is, and no third job starts."""
    h = Review(world, monkeypatch, land_into="checked")
    _move_pr(world, 1)
    world.gh.put(2, head := world.change({"old_proto/x.py": "X = 2\n"}))
    h.tick()
    move = _member(world, 1)
    jobs[0].end(137, "Killed")
    h.clock += 600
    h.tick()
    assert [j.head for j in jobs] == [head, head] and world.on_next(h.q) == [1], world.logs
    assert any(f"the restack of {head[:12]} across the move {move[:12]} ended with no result (exit 137: Killed); once more" in x
               for x in world.logs), world.logs
    st = h.q.status()
    assert st[2].state == "waiting" and st[2].why.startswith(f"{RESTACKING} {move[:12]} ({MAP}) since 13:46 UTC"), st[2]
    h.clock += Q.RESTACK_LOST_S + 1
    h.tick()
    failed = f"{Q.RESTACK} failed (no exit written {Q.RESTACK_LOST_S // 60} min after its start)"
    assert len(jobs) == 2 and world.on_next(h.q) == [1], world.logs
    st = h.q.status()
    assert st[2].state == "refused" and f"it doesn't cross the move {move[:12]} ({MAP}): {failed}" in st[2].why, st[2]
    assert any(p.startswith("@ci @lane-2 queue: #2") and failed in p for p in h.posts), h.posts
    h.tick()
    assert len(jobs) == 2, world.logs                             # the failure is cached: no job starts again


def test_a_restack_job_whose_process_is_gone_with_no_exit_runs_once_more_and_leaves_nothing(world, monkeypatch, jobs):
    """A restart of the pod leaves a job with no exit and no process: the next sync runs it once more and removes the lost
    job's directories."""
    h = Review(world, monkeypatch, land_into="checked")
    _move_pr(world, 1)
    world.gh.put(2, head := world.change({"old_proto/x.py": "X = 2\n"}))
    h.tick()
    gone = subprocess.Popen(["true"])
    gone.wait()
    state = h.q.load_state()
    (lost,) = state["restacking"].values()
    lost["pid"] = gone.pid
    h.q.save_state(state)
    h.tick()
    assert [j.head for j in jobs] == [head, head] and world.on_next(h.q) == [1], world.logs
    assert any(f"the restack of {head[:12]} across the move {_member(world, 1)[:12]} ended with no result (its process is gone "
               "with no exit written" in x for x in world.logs), world.logs
    assert not Path(lost["dir"]).exists() and not Path(lost["out"]).exists()


def test_a_restack_job_is_saved_as_it_starts_so_a_sync_that_fails_after_starting_it_leaves_no_second(world, monkeypatch, jobs):
    """A job is in the state from its start, as drive's launches are: the sync that started it fails before its own save (here
    at its last step), and the next finds the job running and starts no second `restack.py` for the head."""
    h = Review(world, monkeypatch, land_into="checked")
    _move_pr(world, 1)
    world.gh.put(2, head := world.change({"old_proto/x.py": "X = 2\n"}))
    monkeypatch.setattr(h.q, "_keep_merges", None)
    with pytest.raises(TypeError):
        h.tick()
    assert [j.head for j in jobs] == [head], world.logs
    del h.q._keep_merges
    h.tick()
    assert [j.head for j in jobs] == [head] and world.on_next(h.q) == [1], world.logs
    jobs[0].run()
    h.tick()
    assert world.on_next(h.q) == [1, 2], world.logs


def test_a_restacks_result_for_a_head_its_pr_has_left_is_dropped_and_the_new_head_restacked(world, monkeypatch, jobs):
    """The owner pushed a new head while the old one was restacked: the old one's result is read and dropped, never merged,
    and the new head gets a restack of its own."""
    h = Review(world, monkeypatch, land_into="checked")
    _move_pr(world, 1)
    world.gh.put(2, old := world.change({"old_proto/x.py": "X = 1\n"}))
    h.tick()
    move = _member(world, 1)
    world.gh.put(2, new := world.change({"old_proto/x.py": "X = 2\n"}))
    jobs[0].run()
    h.clock += 600
    h.tick()
    assert [j.head for j in jobs] == [old, new] and world.on_next(h.q) == [1], world.logs
    assert any(f"the restack of {old[:12]} across the move {move[:12]} is dropped: its PR's head {old[:8]} changed" in x
               for x in world.logs), world.logs
    assert not [k for k in h.q.load_state()["restacks"] if k.startswith(old)]
    assert h.q.status()[2].why.startswith(f"{RESTACKING} {move[:12]} ({MAP}) since 13:56 UTC")
    jobs[1].run()
    h.tick()
    assert world.on_next(h.q) == [1, 2] and _show(world, _member(world, 2), "new_proto/x.py") == "X = 2", world.logs


def test_a_member_with_a_conflict_of_its_own_above_the_move_is_refused(world, monkeypatch, jobs):
    h = Review(world, monkeypatch, land_into="checked")
    _move_pr(world, 1)
    world.gh.put(2, world.change({"c.txt": "2\n"}))
    world.gh.put(3, world.change({"c.txt": "3\n", "b.py": B.replace("f()", "f() + 3")}))
    h.tick()
    (job,) = jobs
    job.run()
    h.tick()
    assert world.on_next(h.q) == [1, 2], world.logs
    st = h.q.status()
    assert st[3].state == "refused" and "c.txt" in st[3].why and "restacked through the move" in st[3].why, st[3]


def test_a_move_move_check_refuses_is_kept_out_and_its_owner_told_why(world, monkeypatch):
    h = Review(world, monkeypatch, land_into="checked")
    world.gh.put(1, world.change({"fruit.py": "banana = 2\n"}), body=f"Lane `lane-1`.\nMove: {BAD}\n")
    world.gh.put(2, world.change({"c.txt": "2\n"}))
    h.tick()
    assert world.on_next(h.q) == [2], world.logs
    st = h.q.status()
    assert st[1].state == "refused" and "isn't certified" in st[1].why and "move_check.py" in st[1].why, st[1]
    assert any("#1" in p and "isn't certified" in p for p in h.posts), h.posts


def test_a_member_below_the_move_that_makes_move_check_certify_anything_doesnt_change_its_verdict(world, monkeypatch):
    h = Review(world, monkeypatch, land_into="checked")
    world.gh.put(1, world.change({"tools/verity/check/move_check.py": "print('move-check: certified')\n"}))
    world.gh.put(2, world.change({"fruit.py": "banana = 2\n"}), body=f"Lane `lane-2`.\nMove: {BAD}\n")
    h.tick()
    assert world.on_next(h.q) == [1], world.logs
    st = h.q.status()
    assert st[2].state == "refused" and "isn't certified" in st[2].why, st[2]
    assert any("#2" in p and "isn't certified" in p for p in h.posts), h.posts


def test_a_member_below_the_move_that_changes_its_scripts_holds_it_until_that_member_lands(world, monkeypatch):
    h = Review(world, monkeypatch, land_into="checked")
    rename = (ROOT / "tools/move/rename.py").read_text()
    world.gh.put(1, world.change({"tools/move/rename.py": rename + "# a member's edit\n"}))
    _move_pr(world, 2)
    h.tick()
    assert world.on_next(h.q) == [1], world.logs
    st = h.q.status()
    assert st[2].state == "refused" and "the members below it change tools/move/rename.py" in st[2].why, st[2]
    assert any("#2" in p and "tools/move/rename.py" in p for p in h.posts), h.posts
    h.review(1)
    assert h.tick().startswith("landed #1"), world.logs
    h.tick()                                                      # the sync after the landing regenerates it on `checked`
    move = _member(world, 2)
    assert _parents(world, move) == [_checked(world)] and world.on_next(h.q) == [2], world.logs
